"""Replace entry lines of the apply file by number from a file of new lines, and print the sizes."""
import re, sys
P = 'tmp/apply-checker-2.md'
NEW = sys.argv[1] if len(sys.argv) > 1 else None
s = open(P).read().split('\n')
new = {}
if NEW:
    for l in open(NEW).read().split('\n'):
        m = re.match(r'^- (F-\d+) ', l)
        if m:
            new[m.group(1)] = l
out = []
for l in s:
    m = re.match(r'^- (F-\d+) ', l)
    if m and m.group(1) in new:
        out.append(new[m.group(1)])
    else:
        out.append(l)
open(P, 'w').write('\n'.join(out))
L = [l for l in out if l.startswith('- F-')]
tot = sum(len(l) for l in L)
for l in L:
    print(l[:6], len(l))
print('count', len(L), 'total', tot, 'budget', 600 * len(L))

